{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Restore **25% / AUD 6 million**."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Replace AUD 25,000 de minimis with **AUD 5,000**, and AUD 250,000 deductible basket with an **AUD 50,000 tipping basket**"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Restore **24 months after Completion**."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Reject treatment under the general regime. Require a **separate 100% cap and at least six years**"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly carve out **fraud, wilful concealment and deliberate misconduct** from all caps, baskets, time limits, exclusive remedies and non-reliance provisions"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of the whole data room, accounts, registers and public records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the blanket exclusion for Buyer/adviser knowledge and matters “discoverable” through searches."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require effective consent **and evidence that its conditions are satisfied before Completion**."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Obtain a current payout statement, provide for direct repayment from Completion funds, and require effective security releases."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Include a specific line item for triggered bonuses **plus applicable triggered on-costs**, or an enforceable Seller-funded arrangement."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Preserve the SOW3 cure and broaden the narrow indemnity to address the relevant IP ownership, assignment and related exposure"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require preservation of logs and relevant evidence, investigation, and continuing updates"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Neither accept the Seller’s ordinary-course label without analysis nor automatically classify the amount as Debt or deduct it from price."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Keep Title, Tax, IP, payment obligations and covenants distinct, with express treatment rather than a hidden general-regime override."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require independent evidence of ownership, absence of encumbrances and authority to sell"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Reject the assertion that Tax and IP are settled under the general regime. **Both remain open**; assume neither unlimited liability nor agreement."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

